import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int m = nextInt();
        long[] d = new long[m];
        for (int i = 0; i < m; i++) d[i] = nextLong();
        // Pack (difficulty, profit) into one long so a primitive sort orders by difficulty, then profit.
        long[] dish = new long[m];
        for (int i = 0; i < m; i++) dish[i] = d[i] << 31 | nextLong();
        Arrays.sort(dish);
        long[] ds = new long[m], best = new long[m];
        long mx = 0;
        for (int i = 0; i < m; i++) {
            mx = Math.max(mx, dish[i] & ((1L << 31) - 1));
            ds[i] = dish[i] >> 31;
            best[i] = mx;
        }
        long total = 0;
        for (long x : a) {
            int lo = 0, hi = m;  // first index with ds > x
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ds[mid] <= x) lo = mid + 1;
                else hi = mid;
            }
            if (lo > 0) total += best[lo - 1];
        }
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	m := nextInt()
	d := make([]int, m)
	for i := range d {
		d[i] = nextInt()
	}
	// Pack (difficulty, profit) so a plain sort orders by difficulty, then profit.
	dish := make([]int, m)
	for i := range dish {
		dish[i] = d[i]<<31 | nextInt()
	}
	slices.Sort(dish)
	ds, best := make([]int, m), make([]int, m)
	mx := 0
	for i, v := range dish {
		mx = max(mx, v&(1<<31-1))
		ds[i] = v >> 31
		best[i] = mx
	}
	total := 0
	for _, x := range a {
		i := sort.Search(m, func(k int) bool { return ds[k] > x })
		if i > 0 {
			total += best[i-1]
		}
	}
	fmt.Println(total)
}
